def get_all_transfer_ids() -> list:
    return [t["id"] for t in TRANSFERS]


def get_transfer_by_id(transfer_id: int) -> dict | None:
    for t in TRANSFERS:
        if t["id"] == transfer_id:
            return t
    return None


def format_amount(amount: float) -> str:
    if amount == int(amount):
        return str(int(amount))
    return f"{amount:g}"
